Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pii = pair<int, int>;
const int INF = 1e9;
const int MOD = 1000000007;

int dist[15][15][15][15];
int flow[400][400];
char scienceLab[20][20];
char reactions[20][20];
int dRow[4] = {1, 0, -1, 0};
int dCol[4] = {0, 1, 0, -1};
int iter = 3;
int visited[400];

int rows, T;
int augment(int node, int dest, int bottleneck) {
    if (node == dest) return bottleneck;
    if (visited[node] == iter) return 0;
    visited[node] = iter;
    for (int nextNode = 0; nextNode <= dest; ++nextNode) {
        if (flow[node][nextNode] > 0) {
            int pushed = augment(nextNode, dest, min(bottleneck, flow[node][nextNode]));
            if (pushed > 0) {
                flow[node][nextNode] -= pushed;
                flow[nextNode][node] += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

inline int toID(int r, int c) {
    return (r - 1) * rows + (c - 1);
}

int reach[13][13];
int tmpReach[13][13];

void expand(int val) {
    memcpy(tmpReach, reach, sizeof(reach));
    for (int r = 1; r <= rows; ++r) {
        for (int c = 1; c <= rows; ++c) {
            if (tmpReach[r][c] == val) {
                for (int dir = 0; dir < 4; ++dir) {
                    int nr = r + dRow[dir];
                    int nc = c + dCol[dir];
                    if (nr >= 1 && nc >= 1 && nr <= rows && nc <= rows && reach[nr][nc] < val && scienceLab[nr][nc] != 'Y') {
                        reach[nr][nc] = val;
                    }
                }
            }
        }
    }
}

bool reachable(int sr, int sc, int tr, int tc, int infx, int infy) {
    memset(reach, 0, sizeof(reach));
    reach[sr][sc] = 1;
    reach[infx][infy] = 2;
    for (int iter2 = 0; iter2 < 100; ++iter2) {
        expand(1);
        if (reach[tr][tc] == 1) return true;
        expand(2);
        if (reach[tr][tc] == 2) return false;
    }
    return false;
}

int main() {
    ios::sync_with_stdio(0); cin.tie(0);

    int infx = -1, infy = -1;
    memset(dist, 1, sizeof(dist));
    cin >> rows >> T;

    for (int i = 1; i <= rows; ++i) {
        cin >> (scienceLab[i] + 1);
        for (int j = 1; j <= rows; ++j) {
            dist[i][j][i][j] = 0;
            if (scienceLab[i][j] == 'Z') {
                infx = i; infy = j;
            }
        }
    }

    for (int i = 1; i <= rows; ++i) {
        cin >> (reactions[i] + 1);
    }

    for (int i = 1; i <= rows; ++i) {
        for (int j = 1; j <= rows; ++j) {
            for (int dir = 0; dir < 4; ++dir) {
                int ni = i + dRow[dir];
                int nj = j + dCol[dir];
                if (ni >= 1 && nj >= 1 && ni <= rows && nj <= rows) {
                    if (scienceLab[i][j] != 'Y' && scienceLab[ni][nj] != 'Y') {
                        dist[i][j][ni][nj] = 1;
                    }
                }
            }
        }
    }

    for (int k = 1; k <= rows; ++k) {
        for (int l = 1; l <= rows; ++l) {
            for (int i = 1; i <= rows; ++i) {
                for (int j = 1; j <= rows; ++j) {
                    for (int m = 1; m <= rows; ++m) {
                        for (int n = 1; n <= rows; ++n) {
                            dist[i][j][m][n] = min(dist[i][j][m][n], dist[i][j][k][l] + dist[k][l][m][n]);
                        }
                    }
                }
            }
        }
    }

    int source = rows * rows * 2 + 1;
    int sink = rows * rows * 2 + 2;

    for (int i = 1; i <= rows; ++i) {
        for (int j = 1; j <= rows; ++j) {
            if (isdigit(scienceLab[i][j])) {
                flow[source][toID(i, j)] = scienceLab[i][j] - '0';
            }
            if (isdigit(reactions[i][j])) {
                flow[rows * rows + toID(i, j)][sink] = reactions[i][j] - '0';
            }

            if (isdigit(scienceLab[i][j])) {
                for (int u = 1; u <= rows; ++u) {
                    for (int v = 1; v <= rows; ++v) {
                        if (scienceLab[i][j] > '0' && reactions[u][v] > '0') {
                            if (isdigit(reactions[u][v]) && dist[i][j][u][v] <= T && reachable(i, j, u, v, infx, infy)) {
                                flow[toID(i, j)][rows * rows + toID(u, v)] = 1000;
                            }
                        }
                    }
                }
            }
        }
    }

    int maxFlow = 0;
    int pushed;
    while ((pushed = augment(source, sink, 1000))) {
        maxFlow += pushed;
        ++iter;
    }

    cout << maxFlow << '\n';
    return 0;
}
